package com.adalat.service.ai;
import com.adalat.dto.ai.AiIntakeRequestDTO;
import com.adalat.dto.ai.AiIntakeResponseDTO;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpHeaders; import org.springframework.http.MediaType; import org.springframework.stereotype.Service; import org.springframework.web.reactive.function.client.WebClient; import org.springframework.web.reactive.function.client.WebClientResponseException; import org.springframework.web.reactive.function.client.WebClientRequestException; import reactor.core.publisher.Mono; import reactor.util.retry.Retry;  import java.net.UnknownHostException; import java.net.ConnectException; import java.time.Duration; import java.util.List; import java.util.Map; import java.util.concurrent.TimeoutException;  @Slf4j @Service public class ExternalLlmLegalAiProvider implements LegalAiProvider {      private final WebClient webClient;     private final AiProperties aiProperties;     private final ObjectMapper objectMapper;      public ExternalLlmLegalAiProvider(WebClient.Builder webClientBuilder, AiProperties aiProperties, ObjectMapper objectMapper) {         this.aiProperties = aiProperties;         this.objectMapper = objectMapper;         this.webClient = webClientBuilder                 .baseUrl(aiProperties.getBaseUrl())                 .defaultHeader("x-goog-api-key", aiProperties.getApiKey())                 .defaultHeader(HttpHeaders.CONTENT_TYPE, MediaType.APPLICATION_JSON_VALUE)                 .build();     }      @Override     public AiIntakeResponseDTO processMessage(AiIntakeRequestDTO request) {         boolean keyPresent = aiProperties.getApiKey() != null && !aiProperties.getApiKey().isBlank();          if (!keyPresent) {             log.warn("AI API Key is not configured. Returning fallback response.");             throw new AiProviderException(AiProviderException.ErrorCategory.AUTH_ERROR, "AI configuration is missing.");         }          try {             String systemMessage = buildSystemPrompt(request);              Map<String, Object> payload = Map.of(                     "system_instruction", Map.of("parts", List.of(Map.of("text", systemMessage))),                     "contents", List.of(                             Map.of(                                 "role", "user",                                 "parts", List.of(Map.of("text", request.getLatestCustomerMessage() != null ? request.getLatestCustomerMessage() : ""))                             )                     ),                     "generationConfig", Map.of(                             "temperature", 0.2,                             "responseMimeType", "application/json"                     )             );              String uri = "/v1beta/models/" + aiProperties.getModel() + ":generateContent";              long start = System.currentTimeMillis();             String responseBody = webClient.post()                     .uri(uri)                     .bodyValue(payload)                     .retrieve()                     .bodyToMono(String.class)                     .timeout(Duration.ofSeconds(aiProperties.getTimeoutSeconds()))
                    .retryWhen(Retry.backoff(1, Duration.ofSeconds(1))
                        .filter(this::isTransientError)
                        .onRetryExhaustedThrow((retryBackoffSpec, retrySignal) -> {
                            Throwable e = retrySignal.failure();
                            log.warn("Gemini retries exhausted after {} attempts: {}", retrySignal.totalRetries(), e.getMessage());
                            return mapException(e);
                        })
                    )                     .onErrorMap(e -> !(e instanceof AiProviderException), this::mapException)                     .block();                                  long latency = System.currentTimeMillis() - start;             log.info("Provider latency: {} ms", latency);              return parseResponse(responseBody);          } catch (AiProviderException e) {             throw e;         } catch (Exception e) {             log.error("DEBUG: exception class/message: {} - {}", e.getClass().getName(), e.getMessage());             throw new AiProviderException(AiProviderException.ErrorCategory.UNKNOWN_PROVIDER_ERROR, "Unexpected error during AI processing", e);         }     }      private boolean isTransientError(Throwable t) {         if (t instanceof TimeoutException) {             return true;         }         if (t instanceof WebClientRequestException || t instanceof UnknownHostException || t instanceof ConnectException) {             return true;         }         if (t instanceof WebClientResponseException) {             int status = ((WebClientResponseException) t).getStatusCode().value();             return status == 503 || status == 502 || status == 504;         }         return false;     }      private AiProviderException mapException(Throwable e) {         if (e instanceof WebClientResponseException wce) {             int status = wce.getStatusCode().value();             if (status == 429) {                 return new AiProviderException(AiProviderException.ErrorCategory.QUOTA_EXCEEDED, "Quota exceeded: " + status);             } else if (status == 503 || status == 502 || status == 504) {                 return new AiProviderException(AiProviderException.ErrorCategory.PROVIDER_OVERLOADED, "Provider overloaded: " + status);             } else if (status == 401 || status == 403) {                 return new AiProviderException(AiProviderException.ErrorCategory.AUTH_ERROR, "Auth error: " + status);             } else {                 return new AiProviderException(AiProviderException.ErrorCategory.UNKNOWN_PROVIDER_ERROR, "External AI provider returned an error: " + status);             }         } else if (e instanceof TimeoutException) {             return new AiProviderException(AiProviderException.ErrorCategory.TIMEOUT, "AI provider timed out.");         } else if (e instanceof WebClientRequestException || e instanceof UnknownHostException || e instanceof ConnectException) {             return new AiProviderException(AiProviderException.ErrorCategory.NETWORK_ERROR, "Network error connecting to AI provider.", e);         }         return new AiProviderException(AiProviderException.ErrorCategory.UNKNOWN_PROVIDER_ERROR, "Unexpected error: " + e.getMessage(), e);     }      private String cachedDefaultSystemRules;      private synchronized String getDefaultSystemRules() {         if (cachedDefaultSystemRules == null) {             try (java.io.InputStream is = new org.springframework.core.io.ClassPathResource("prompts/legal_assistant_prompt.txt").getInputStream()) {                 cachedDefaultSystemRules = new String(is.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);             } catch (Exception e) {                 log.warn("Could not load prompts/legal_assistant_prompt.txt from classpath, falling back to default.", e);                 cachedDefaultSystemRules = "You are ADALAT AI LEGAL ASSISTANT, an intelligent legal intake assistant for Adalat in India.";             }         }         return cachedDefaultSystemRules;     }      private String buildSystemPrompt(AiIntakeRequestDTO request) throws JsonProcessingException {         String baseRules = getDefaultSystemRules();          if (request.getSystemRules() != null && !request.getSystemRules().isBlank()) {             baseRules += "\n\n" + request.getSystemRules();         }          String stateJson = objectMapper.writeValueAsString(request.getCurrentState() != null ? request.getCurrentState() : Map.of());         String askedFactKeysJson = objectMapper.writeValueAsString(request.getAskedFactKeys() != null ? request.getAskedFactKeys() : List.of());         String askedQuestionsJson = objectMapper.writeValueAsString(request.getAskedQuestions() != null ? request.getAskedQuestions() : List.of());         String missingFactsJson = objectMapper.writeValueAsString(request.getMissingCriticalFacts() != null ? request.getMissingCriticalFacts() : List.of());                  String previousFactKey = request.getPreviousQuestionFactKey() != null ? request.getPreviousQuestionFactKey() : "NONE";         String previousFactText = request.getPreviousQuestionText() != null ? request.getPreviousQuestionText() : "NONE";          return baseRules + "\n\n" +                 "==================================================\n" +                 "DYNAMIC CONVERSATION CONTEXT PROVIDED BY BACKEND\n" +                 "==================================================\n" +                 "PREVIOUS_QUESTION_FACT_KEY: " + previousFactKey + "\n" +                 "PREVIOUS_QUESTION_TEXT: " + previousFactText + "\n\n" +                 "CURRENT_STATE:\n" + stateJson + "\n\n" +                 "ASKED_FACT_KEYS:\n" + askedFactKeysJson + "\n\n" +                 "ASKED_QUESTIONS:\n" + askedQuestionsJson + "\n\n" +                 "MISSING_CRITICAL_FACTS:\n" + missingFactsJson + "\n\n" +                 "LATEST_CUSTOMER_MESSAGE:\n" + (request.getLatestCustomerMessage() != null ? request.getLatestCustomerMessage() : "") + "\n\n" +                 "REMINDER: Return strictly a valid JSON object with no markdown wrapping. Do NOT include a thoughtProcess field or any reasoning fields. Only include the following fields: assistantMessage, primaryCategory, secondaryCategories, jurisdiction, newFacts, urgency, missingCriticalFacts, nextQuestionFactKey, nextQuestion, intakeComplete, customerSummary, lawyerSummary.";     }      private AiIntakeResponseDTO parseResponse(String responseBody) throws JsonProcessingException {         try {             Map<String, Object> responseMap = objectMapper.readValue(responseBody, Map.class);             List<Map<String, Object>> candidates = (List<Map<String, Object>>) responseMap.get("candidates");                          if (candidates == null || candidates.isEmpty()) {                 throw new AiProviderException(AiProviderException.ErrorCategory.INVALID_PROVIDER_RESPONSE, "AI returned empty candidates.");             }              Map<String, Object> contentMap = (Map<String, Object>) candidates.get(0).get("content");             if (contentMap == null) {                 throw new AiProviderException(AiProviderException.ErrorCategory.INVALID_PROVIDER_RESPONSE, "AI returned null content map.");             }              List<Map<String, Object>> parts = (List<Map<String, Object>>) contentMap.get("parts");                          if (parts == null || parts.isEmpty()) {                 throw new AiProviderException(AiProviderException.ErrorCategory.INVALID_PROVIDER_RESPONSE, "AI returned null parts.");             }                          String content = (String) parts.get(0).get("text");              if (content == null || content.isBlank()) {                 throw new AiProviderException(AiProviderException.ErrorCategory.INVALID_PROVIDER_RESPONSE, "AI returned empty text in parts.");             }              try {                 AiIntakeResponseDTO dto = objectMapper.readValue(content, AiIntakeResponseDTO.class);                 return dto;             } catch (JsonProcessingException e) {                 throw new AiProviderException(AiProviderException.ErrorCategory.JSON_PARSE_ERROR, "JSON Parse Error", e);             }         } catch (JsonProcessingException e) {             throw new AiProviderException(AiProviderException.ErrorCategory.JSON_PARSE_ERROR, "Failed to parse provider response body", e);         }     } }